using NeonSidekick.App;

namespace NeonSidekick.Help;

/// <summary>
/// What <c>neon_help</c> and <c>/help</c> say on macOS where Windows' text would name the wrong system (2026-10-06, the tidy-up
/// before the first Mac release: a Mac user never reads Windows wording). A layer over <see cref="HelpSettings"/> and
/// <see cref="HelpCommands"/>, used only when <see cref="OperatingSystem.IsMacOS"/>, so Windows' sentences stay byte for byte as
/// they were (many are pinned). A setting or a form missing here keeps its one text, true on both systems. A feature that needs
/// Windows says so, in its area's own words where it has them (<c>/keycheck</c> did until 2026-10-11, when it came to a Mac over
/// Carbon); printing came on 2026-10-08 (CUPS), so its
/// rows say how a Mac prints. The camera works on a Mac since 2026-10-07 (AVFoundation), so its rows say where macOS differs: the devices it lists
/// and the permission that is the terminal's. The embedded LLM runs on a Mac since 2026-10-07 (Metal), so its rows here say how it differs, not that it is missing; pictures
/// came the same day (ImageIO), so <c>Embedded vision</c> needs no Mac text any more. YouTube playback came later that day (WebKit,
/// macOS 14 or later), so its rows say what the Mac's window needs and its keys. The Docker tools came on 2026-10-11 (the engine's Unix
/// socket), so their rows say how a Mac finds the engine; Docker servers say why they still need Windows.
/// <c>HelpMacTests</c> pins that every key still names a setting or a form the tables hold, so the layer cannot go stale.
/// </summary>
public static class HelpMac
{
    /// <summary>The settings whose text differs on a Mac, by field.</summary>
    public static readonly IReadOnlyDictionary<SettingsField, string> Settings = new Dictionary<SettingsField, string>
    {
        [SettingsField.LlmApiKey] = "The bearer token the server expects; leave it empty for a local server that needs none. A key is saved encrypted under a key the app keeps in your macOS Keychain and shown as `(set, encrypted)`. Typing a new value replaces it (`empty` stays as it is).",
        [SettingsField.ExternalSkills] = "Also reads the skills in `~/.agents/skills`, read-only.",
        [SettingsField.DraftEditor] = "The program `/draft` opens its temporary file with (`code --wait`, `nano`…); it must wait until the file is closed. Empty uses the app macOS opens `.txt` files with (TextEdit unless you chose another).",
        [SettingsField.ShellOutputMaxChars] = "The most output one result carries back (2000–500000). Past that, the start and end are kept, and the whole text goes to `.shell/<id>.log` under the working directory, where `read_file` can reach it.",
        [SettingsField.SqlSetPassword] = "Pick a connection that takes a password (`sql` or `runas`) and type it, masked. It is saved to that connection's store: encrypted in its `sql.json`, or in the macOS Keychain. `windows` sign-in (Kerberos, your ticket) needs none.",
        [SettingsField.WelcomeSplash] = "Shows pictures under the banner at startup until you send the first line: `fullsize`, `tiled` or `off`. `fullsize`: one picture; ←/→ step through the set. `tiled`: thumbnails at *Image thumbnail size*. Pictures in the profile's `images/splash_images/` folder replace the built-in ones; `/splash` shows the splash whatever the setting.",   // 2026-10-10, the folder moved under images
        [SettingsField.ComfyOutputFolder] ="The folder under the profile's `images` folder the pictures are saved in (`comfy_images/pony-txt2img-1234.png`), kept out of the working directory. Empty uses the `images` folder itself.",
        [SettingsField.PastedImagesFolder] = "The folder under the profile's `images` folder a picture pasted from the clipboard is saved in when its message is sent (`pasted_images/pasted-20261009-142233.png`), made on first use. The message tells the model the file's path, so its picture tools can use it. Empty uses the `images` folder itself. A dropped file is not copied.",
        [SettingsField.ImageEditor] = "Where a double-clicked picture, or one the model opens with `open`, opens. Empty: the built-in picture viewer (with no desktop to draw on, over SSH, the app macOS opens the file type with). `system`: the app macOS opens the file type with (Preview unless you chose another). Anything else is a command, with the file's path appended (`open -a Preview`).",
        [SettingsField.ClaudeCodeExecutable] = "The Claude Code CLI to run. Blank looks for `claude` on the PATH, then `~/.local/bin/claude` (where the native installer puts it). A path you set must exist; it is never swapped for another.",
        [SettingsField.AnthropicApiKey] = "Your Anthropic API key (`sk-ant-…`), saved encrypted under the app's key in your macOS Keychain and shown as `(set, encrypted)`. Typing replaces it; an empty entry clears it.",
        [SettingsField.OpenAIApiKey] = "Your OpenAI API key (`sk-…`), saved encrypted under the app's key in your macOS Keychain and shown as `(set, encrypted)`. Typing (masked) replaces it; an empty entry clears it. It goes only to api.openai.com, never to a local server or the Anthropic API.",
        [SettingsField.ThemedExternalWindows] = "The app's own windows wear the theme: the theme's colors, with a dark or light title bar to match. On a Mac they are the picture viewer, the thumbnail browser, the camera's live window, the log and process windows and the video window (the picture menu is the system's, dark or light with the window). Off, they stay black.",
        [SettingsField.HomeAssistantToken] = "A long-lived access token (in Home Assistant: your profile → Security → Long-lived access tokens). It is typed into a masked field and saved encrypted under the app's key in your macOS Keychain; empty clears it. Never written to the log.",
        [SettingsField.YouTubeTools] = "Offers the YouTube tools: search, playback in the app's video window, and the profile's saved videos. `youtube_search` and `youtube_playlist` need a *YouTube API key*; `youtube_play`, `youtube_control` and `youtube_status` play a video or a public playlist in the video window (macOS 14 or later, on the Mac's desktop, through Safari's WebKit); `youtube_saved` and `youtube_save` keep videos, each resuming where it was left. Playing by a video's or playlist's id or link needs no key. A headless run offers the search, the playlist listing and the saved videos. `/youtube` works either way. The top of its on/off page has **max** (`m`), **voice** (`v`), **order** (`o`) and **safe** (`s`) buttons that open *YouTube search max results*, *YouTube while speaking*, *YouTube search order* and *YouTube safe search*; ESC there comes back.",   // 2026-10-07, the saved videos with main's
        [SettingsField.YouTubeApiKey] = "Your YouTube Data API v3 key, for searching. Make one in the Google Cloud Console: create a project, enable YouTube Data API v3 (APIs & Services › Library), create an API key under Credentials and restrict it to that API, with no application restriction. A search costs 100 of the project's 10,000 free units a day (about 100 searches). Typed into a masked field and saved encrypted under the app's key in your macOS Keychain; empty clears it. `/profile push keys` copies it and a plain `/profile reset` keeps it. Never written to the log.",
        [SettingsField.PdfEngine] = "What makes a PDF for `convert_to_pdf` and `/pdf`. `auto` and `browser`: Edge, Chrome, Brave or Chromium from `/Applications`. `printer` (Microsoft Print to PDF) needs Windows.",
        [SettingsField.UncTools] = "Offers the UNC tools over the shares in `unc.json`, once one is defined: `unc_shares`, `unc_search`, `unc_info`, `unc_read`, and `unc_fetch` while *File tools* is on. On a Mac a share is `smb://server/share` (a Windows file's `\\\\server\\share` reads as it) or a local `/folder`. The app mounts an `smb://` share itself on first use, under `/Volumes`, hidden from Finder, read-only for an `access: read` share, and unmounts it when it exits; while it is mounted, anything you run can reach it too, and only the shell police keeps the model's shell off it. The top of its on/off page (`/tools unc`, the toolbar's 🔗) has an **offered** button (`o`) that shows how many are offered and opens *UNC shares offered*.",   // a Mac mounts shares since 2026-10-11
        [SettingsField.DockerTools] = "Offers the Docker tools: `docker_containers`, `docker_logs`, `docker_inspect`, `docker_stats`, `docker_resources` and `docker_compose`, over the engine's Unix socket (Docker Desktop, OrbStack, Colima or Rancher Desktop; *Docker engine socket* says which). They are offered whether the engine runs or not (they say when it does not). `/docker` works either way. On a Mac the engine runs in a Linux VM, so the CPU and memory figures are the VM's. The top of its on/off page (`/tools docker`, the toolbar's 🐳) has a **manage** (`m`) button that opens `/docker`'s container list; ESC there comes back.",   // a Mac's socket, 2026-10-11
        [SettingsField.DockerServers] = "Docker servers need Windows: Docker Desktop on a Mac passes no GPU to containers (the engine refuses an NVIDIA device), so vLLM and SGLang containers cannot serve there. On a Mac the embedded model runs on Metal instead (see *Embedded*).",   // 2026-10-11, measured
        [SettingsField.SqlAddConnection] = "A wizard for a new connection, one page per choice, or to edit a saved one. It signs in with a SQL login or, through Kerberos, with Windows sign-in as you (your ticket, no password) or with runas as another account (`name@REALM` and its stored password: the app gets that account's ticket at each connect, and macOS keeps it in a cache of its own beside yours). It can **test** the draft (`SELECT @@VERSION`, then the other databases the login could open) before saving it. The database is required: the connection reaches that one alone. With entries saved, its first page lists them: + New, or one to edit, which opens on its summary prefilled (Enter on a row changes it; its file kept, the stored password kept unless another is typed).",
        [SettingsField.SttInput] = "Turns the microphone on: the push-to-talk key records a spoken message (`/stt`). macOS asks once whether your terminal app (Terminal, iTerm2…) may use the microphone; if it was refused, turn it on in System Settings › Privacy & Security › Microphone. A MacBook's own microphone is off while its lid is closed: pick another input in System Settings › Sound.",
        [SettingsField.PrintTools] = "Offers `list_printers` and `print_file` to the model, over the printers set up in System Settings › Printers & Scanners. `/print` works either way. The top of its on/off page (`/tools print`, the toolbar's 🖨️) has a **printer** button (`p`) that opens *Print default printer*; ESC there comes back.",   // a Mac prints since 2026-10-08
        [SettingsField.PrintDefaultPrinter] = "The printer a print goes to when none is named, picked from the printers set up on this Mac (each listed by its queue name and the name System Settings shows). `(system default)` uses the Mac's default printer.",
        [SettingsField.ShowPerformanceBar] = "A checklist of the meters on the performance bar, updated once a second. The meters: **CPU**, **RAM** (Activity Monitor's Memory Used: app memory, wired and compressed), **GPU**, **GMEM** (a Mac's GPU has no memory of its own: the memory it holds, as a share of the part macOS lets it use), **NET** (network use as a share of the link speed; on Wi-Fi the radio's current rate), **NET↓** and **NET↑** (download and upload rates in bits per second) and **PROC** (the model's background processes still running; `/process` lists them). `/perfbar edit` opens it too. Enter or Space flips one; Delete unchecks it; `a` / `n` / `d` check all, none or the default (which puts the order and sides back too); none hides the bar. The checklist has three groups, *Pinned left*, *Pinned center* and *Pinned right*: Shift+←/→ (or Alt+←/→) pins the meter under the cursor a group over, Shift+↑↓ (or Alt+↑↓) moves it a place (crossing into the next group at its edge) and Shift+Home/End to its group's top or bottom; a bar never pinned is centered. `/perfbar text`, `gauge` or `led` picks the look. Values turn amber from 60 % and red from 85 %; a meter the machine cannot read is left out. On a narrow row the meters shrink, then fall back to the numbers, then the side groups give way; the center wins. A double-click or a right-click on the bar opens `/settings`. `/perfbar` or the toolbar's 📈 hides the bar or shows it again.",
        [SettingsField.OracleSetPassword] = "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `oracle.json`, or in the macOS Keychain.",
        [SettingsField.MySqlSetPassword] = "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `mysql.json`, or in the macOS Keychain.",
        [SettingsField.UncSetPassword] = "Pick a runas share and type its password, masked. It is saved to that share's store: encrypted in its `unc.json`, or in the macOS Keychain. A runas share is mounted as that account (`name@REALM`, `DOMAIN\\name`, or the server's own account name) until the app exits.",   // 2026-10-11
        [SettingsField.EmbeddedBackend] = "Which llama.cpp build runs the model. On a Mac there is one, Metal, which uses the Apple Silicon GPU: `auto` and `metal` both pick it. The row shows what `auto` picked.",
        [SettingsField.EmbeddedVramBudget] = "How much of the GPU's memory the embedded server may fill: `off` (llama.cpp leaves 1 GiB free) or 50–99 %. On a Mac the GPU shares the computer's memory, so the budget is a share of the part macOS lets the GPU use (about two thirds of a 16 GB Mac's memory). It adjusts only what is left to fit: with *Embedded context length* 0 the context shrinks first, then, with *Embedded GPU layers* `auto`, layers move to the CPU, which slows replies sharply; so it works best with context 0. It is measured when the server starts; a change restarts the server.",
        [SettingsField.EmbeddedVramOnly] = "Keeps the embedded model on the GPU: every layer goes on the GPU (whatever *Embedded GPU layers* says; with *Embedded context length* 0 the context shrinks to fit instead). If llama.cpp still leaves layers on the CPU, or a buffer could not be allocated, the server stops and the connect says what to lower. On a Mac the GPU shares the computer's memory, so this checks where the layers went, not which memory holds them. Refused when llama-server does not report where it put the layers.",
        [SettingsField.ImageEditQuality] = "The quality `image_edit` writes a JPEG or HEIF at when the model gives none (1–100), and where `max_kb` starts lowering it from. A Mac's ImageIO writes no JPEG XL.",
        [SettingsField.DockerEnginePipe] = "*Docker engine socket* on a Mac: the engine's Unix socket, a path (`/var/run/docker.sock`, `~/.orbstack/run/docker.sock`) or `unix:///path`. Empty (or Windows' pipe name, `docker_engine`) finds it the way the `docker` command does: `DOCKER_HOST`, then the Docker CLI's current context (either used even when its socket is gone, as `docker` does; a `tcp://` or `ssh://` one is refused, since the tools reach only a local socket), then with neither `~/.docker/run/docker.sock`, `/var/run/docker.sock`, `~/.orbstack/run/docker.sock`, `~/.colima/default/docker.sock` and `~/.rd/docker.sock`, in that order. The row shows what it found (`auto: ~/.docker/run/docker.sock`); anything typed there that is not a full path or `unix:///path` is refused.",   // 2026-10-11
        [SettingsField.CameraDevice] = "The camera, by the name macOS lists it under (the built-in FaceTime camera, a USB webcam, an iPhone as Continuity Camera), picked from the ones connected. `(first camera)` uses the first; a MacBook's own camera lists last while its lid is closed. A camera that is not connected uses the first, with a notice.",
        [SettingsField.ScreenTools] = "Offers `screen_capture` and `screen_list`, which let the model see a monitor, every monitor or one window. Never offered without the pane, headless, or to an embedded model without its vision projector. `/screen` works either way. The terminal app the app runs in (Terminal, iTerm2…) needs the Screen Recording permission: macOS asks once, at the first capture; turn it on in " + Screen.ScreenText.PermissionPage + ", then quit and reopen the terminal. Without it nothing is captured and no window is listed. The top of its on/off page has **ask** (`a`) and **preview** (`p`) buttons that open *Screen policy* and *Screen preview*; ESC there comes back.",
        [SettingsField.ShoppingTools] = "Offers the shopping list's tools, for the list itself and for the stores' layouts. The list: `shopping_list`, `shopping_add`, `shopping_check`, `shopping_remove` and `shopping_clear` (the whole list only after your yes on the pane). The layouts: `shopping_locate`, `shopping_place`, `shopping_stores`, `shopping_layout`, `shopping_recent` and `shopping_reference` (a store's reference documents: PDFs, text files, pictures). Everything lives in the profile's `db/shopping/shopping.db`, each store's documents in `db/shopping/reference/<store>`. `/tools shopping` opens this switch; the toolbar's 🛒 opens the list itself (`/shopping`).",   // 2026-10-13, the neon_help copy edit: the Windows text's paths
        [SettingsField.PostgresSetPassword] = "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `postgres.json`, or in the macOS Keychain.",
    };

    /// <summary>
    /// <c>/terminal</c> on a Mac (2026-10-07): <c>open</c> starts the terminal the app runs in when it is Terminal or iTerm2, else
    /// Terminal; Terminal opens a window, iTerm2 a tab in its front window (iTerm2's own choice); Ctrl+] for Ctrl+., which a Mac
    /// terminal sends as a bare ".". Pinned.
    /// </summary>
    public const string TerminalForm = "Open a new terminal in the working directory, or in a folder under it (Tab completes the folder): a new Terminal window, or a new tab in iTerm2's front window when the app runs in iTerm2 (its settings can make it a window). Another terminal app opens Terminal. Ctrl+] runs it too (a Mac terminal sends Ctrl+. as a plain dot).";

    /// <summary>
    /// <c>/print</c> on a Mac (2026-10-08, CUPS): drawn into a PDF in Helvetica Neue and Menlo, a PDF sent as it is (with the
    /// printer, copies and pages, never landscape), an Office file refused. Pinned.
    /// </summary>
    public const string PrintFileForm = "Print a file from the working directory: text and code as a listing, Markdown formatted, a picture fitted to one page, each page headed with the file's name, the time and *page N of M*, in Helvetica Neue and Menlo on the printer's own paper. A PDF goes to the printer as it is, with the printer, copies and pages but not landscape; anything else (a Word or Excel file) is refused: print it from the program that made it. `printer=` matches the queue name, the name System Settings shows, or part of either (`printer=brother`; quote a name with spaces); copies are 1–10; pages are `3`, `1-3`, `4-` or a list such as `1,3-5`. Options go anywhere. *Print action policy* never applies to this command.";

    /// <summary>The command forms whose text differs on a Mac, by syntax as <see cref="HelpCommands"/> writes it.</summary>
    public static readonly IReadOnlyDictionary<string, string> Forms = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["/camera"] = "Open the camera pane to take a photo: Space takes it, `r` takes it again, Enter puts it on the input line as `[Image #N]`, ESC drops it. Under *Camera preview* `live` a camera window of its own shows the shot as you frame it. The photo is saved in the *Camera output folder* under the profile's `images` folder. Without the pane, it takes one at once. The first use asks macOS whether your terminal may use the camera; change a refusal in System Settings › Privacy & Security › Camera.",
        ["/camera list"] = "List the cameras macOS sees in a pane (the built-in camera, USB webcams, an iPhone as Continuity Camera), numbered, the chosen one marked.",
        ["/keycheck"] = "List the app's key chords and whether something keeps each from the app, the taken ones first; `/help`'s Keys tab shows this list too. A chord is taken by a macOS shortcut (System Settings › Keyboard › Keyboard Shortcuts), an app holding it as an exclusive hotkey, or the terminal's Option key typing characters (Terminal's Use Option as Meta key, iTerm2's Esc+), whose setting it reads and names. Hotkeys most apps hold the shared way can't be seen, and keyboard tools (Karabiner, BetterTouchTool) can still take a key; an Apple keyboard's F9 and F10 are media keys unless fn is held.",   // 2026-10-11
        ["/view <image>|<folder>"] = "Open an image from the working directory in the picture viewer, or a folder there on its newest picture. The arrows, the mouse wheel or a two-finger swipe step through the pictures, and a right-click (or Control-click) opens the picture menu (rotate, flip, color, resize, convert, shrink, strip metadata, copy the path, show in Finder, attach, print, delete; edits go where *Image edit mode* says). ⌃⌘F is full screen (F11 too, if macOS's Show Desktop shortcut is off), ⌫ twice deletes, and Esc or ⌘W closes. Drag the picture out to copy its file; TAB brings the terminal forward, and a Ctrl or Option chord runs in the chat. Needs the Mac's desktop (not over SSH). Works while a reply runs.",
        ["/view <image>|<folder> --thumbs"] = "Open the folder (an image's folder, with the image selected) as thumbnails in a window of their own, in step with the picture viewer and the picture strip. A click shows the picture in the viewer, a double-click or Enter opens it there, and the viewer's own moves select it here; new pictures go on the end, so nothing moves. + and −, ⌘ with the wheel or a pinch resize the tiles, F5 lists and fits again, and a right-click (or Control-click) opens the picture menu. `--thumbs` may be the first or last word. Needs the Mac's desktop (not over SSH). Works while a reply runs.",
        ["/log"] = "Open the log window: this run's diagnostic lines, colored by level, following the newest while it is at the bottom. Scrolling away pauses it; ⌘↓, Ctrl+E or scrolling back to the bottom follows again, and ⌘↑ goes to the top. Drag to select, ⌘A selects all, ⌘C copies; ⌃⌘F is full screen, and Esc leaves full screen, then closes the window, as ⌘W does. TAB brings the terminal forward, and any Ctrl or Option chord runs in the chat (Ctrl+G closes the window; Ctrl+C cancels a reply). Needs the Mac's desktop (not over SSH).",
        ["/print <file> [printer=<name>] [copies=<n>] [pages=<range>] [landscape]"] = PrintFileForm,
        ["/print printers"] = "List the printers set up on this Mac in a pane, each by its queue name and the name System Settings shows, marking the system default and *Print default printer*. Alone, `/print` shows how to use it and lists them too.",
        ["/pdf <file> [to=<path>] [paper=letter|a4|legal] [landscape] [overwrite]"] = "Make a PDF of a file in the working directory, beside it unless `to=` names a file or folder; an existing PDF is replaced only with `overwrite`. Markdown keeps its headings, tables, lists, links, colored code and the pictures beside it; text and code become a colored listing; HTML prints as the page, without its scripts or anything outside the working directory; a picture is fitted to one page. Options go anywhere. Edge, Chrome, Brave or Chromium makes it. Alone, `/pdf` shows how to use it.",
        ["/terminal [<folder>]"] = TerminalForm,
        ["/shortcut [<profile>] [--log]"] = "Put a `.command` file on the desktop, `NeonSidekick (<profile>)`, that starts the app in its folder on the loaded profile, or the one named (as `--profile <name>`); double-click it in Finder. With `--log` it also writes a log, `logs/neon-<profile>-{ts}.log` beside the app, named by the time it starts. It wears the app's icon and opens in the terminal `/terminal` opens (iTerm2 when the app runs in it, else Terminal); Get Info › Open with picks another. One already there is replaced.",   // 2026-10-08
        // 2026-10-07, the docs pass: a Mac terminal sends Ctrl+Shift+F as Ctrl+F's byte (0x06, which is /perfbar) and Shift+Enter as a
        // plain CR, so /find is typed there and Shift+F3 (xterm's modifier parameter) is the way back down.
        ["/find [<words>]"] = "Find words in the transcript: a find row opens over the input row, every match is marked, and the transcript scrolls to the newest. Typing changes the words; Enter or F3 goes to the next match up (older), Shift+F3 back down (a Mac terminal sends Shift+Enter as a plain Enter), PgUp/PgDn scroll. Folded blocks that hold a match open, and fold again when the find ends. ESC ends it at the bottom of the transcript. Type `/find`: a Mac terminal sends Ctrl+Shift+F as Ctrl+F, which is `/perfbar`.",
        ["/model [<id>]"] = "Pick a model from the server's list, or set one by its id, as typed (the server is not asked). The list is A to Z with the model in use under the cursor; typing narrows it, Backspace erases, ESC clears it, a second ESC keeps the model. On the embedded LLM, it lists the installed embedded models. Ctrl+D runs it too (a Mac terminal sends Ctrl+M as Enter).",   // 2026-10-07
        ["/youtube play <id>|<link> [<time>]"] = "Play a video by its id or a YouTube link, from the time given (`90` or `1:30`) or the link's own; a link alone plays too. Needs no key. The window opens where it last closed, without taking the keyboard; ⌃⌘F is full screen (F11 too, if macOS's Show Desktop shortcut is off), and Esc leaves it, then closes the window, as ⌘W does. TAB brings the terminal forward. The player's own full-screen button fills a Space of its own, as in Safari; Esc brings it back. Needs macOS 14 or later and the Mac's desktop (not over SSH).",   // 2026-10-07
        ["/screen"] = "Capture the monitor the app is on and put the screenshot on the input line as `[Image #N]`, at the screen's full pixels (a Retina screen at twice its points). It is saved in the *Screen output folder* under the profile's `images` folder, and opens in the picture viewer under *Screen preview*. It is your own hand: *Screen tools* and *Screen policy* never apply. The terminal app needs the Screen Recording permission (" + Screen.ScreenText.PermissionPage + "; quit and reopen the terminal after turning it on).",
        ["/screen window:<id>|<title-words>"] = "Capture one window, even when another covers it: by its id from `/screen list`, or words of its title (or its app's name). A window on another desktop, or minimized, must be brought up first.",
        ["/perfbar [off|text|gauge|led]"] = "Show or hide the performance bar (*Performance bar*). Alone, it hides the bar or shows it again with its last meters (CPU, RAM, GPU and GMEM the first time; GMEM is the GPU's share of the Mac's memory); `off` hides it, and a look (`text`, `gauge`, `led`) sets that look and shows the bar. Works while a reply runs; the toolbar's 📈 and Ctrl+F run it too.",   // 2026-10-07, GMEM
        // 2026-10-13, the neon_help copy edit: forms whose Windows text shows a drive or backslash paths.
        ["/cwd [<path>|~|browse]"] = "Show or change the working directory. A path is a full one, unquoted, and a folder that does not exist is created; once it starts with `/`, the list completes that folder's subfolders. `~` returns to the profile's `files/` folder; `browse` opens the folder picker.",
        ["/cmd <command>"] = "Run a shell line yourself in the working directory, in the *Shell default shell*, its output drawn as it prints; ESC kills it. It passes the model's checks: *Shell command policy* `off` refuses it, the shell police refuse what they refuse under any policy, and under `ask` a line not on *Shell allowed commands* goes to the approval pane. The line and its output go into the conversation, so the model sees them, cut at *Shell output max chars* (the whole in `.shell/cmd_….log`).",
        ["/cmd --bg <command>"] = "Run the line in the background while you chat, after the same checks (with `--shell` too, in either order). `/process` lists it and its window shows the output live; Ctrl+K twice there stops it. When it ends or is stopped, its output is shown (cut at *Shell output max chars*, the whole in `.shell/proc_….log`) and goes into the conversation before your next message; the model's process tool never sees it.",
        ["/shopping reindex [<store>]"] = "Read the active store's reference documents again, or the named one's: every PDF, text file and picture in its folder under `db/shopping/reference`. A changed file is read again on its own; this reads them all.",
    };

    /// <summary><paramref name="field"/>'s text on a Mac, or null where <see cref="HelpSettings"/>' own serves both.</summary>
    public static string? Setting(SettingsField field) => Settings.TryGetValue(field, out string? text) ? text : null;

    /// <summary><paramref name="commands"/> with <see cref="Forms"/>' texts in place, every other form as it was.</summary>
    public static IReadOnlyList<CommandHelp> Apply(IReadOnlyList<CommandHelp> commands)
    {
        ArgumentNullException.ThrowIfNull(commands);
        return commands
            .Select(c => c with { Forms = c.Forms.Select(f => Forms.TryGetValue(f.Syntax, out string? text) ? f with { Meaning = text } : f).ToList() })
            .ToList();
    }
}
